int main(int argc, char** argv) { if (argc < 3) { std::cout << "Usage: protocolx --encode/--decode \"message\"\n"; return 1; } std::string m = argv[1], in = argv[2], out = ""; if (m == "--encode") { for (unsigned char c : in) { std::string s = std::to_string((int)c); while (s.length() < 4) s += 'X'; out += s; } } else if (m == "--decode") { for (size_t i = 0; i < in.length(); i += 4) { std::string b = in.substr(i, 4), n = ""; for (char c : b) if (isdigit(c)) n += c; if (!n.empty()) out += (char)std::stoi(n); } } else { std::cerr << "Error: Invalid mode selection.\n"; return 1; } std::cout << (m == "--encode" ? "Encoded Output: " : "Decoded Output: ") << out << "\n"; return 0; }
